mapper.select:
select baseinfo.prod_id prodId, baseinfo.prod_name prodName, substring(chan2.busi_date,1,7) reportDate, chan2.busi_date as busiDate from chb_prd_baseinfo baseinfo inner join ( SELECT distinct real_prd_id, busi_date FROM prd_own_equity_chan chan
substring(busi_date,1,7) = #{reportDate,jdbcType=VARCHAR}
) chan2 on chan2.real_prd_id = baseinfo.prod_id
#{items,jdbcType=VARCHAR}

select chan.real_prd_id realPrdId, chan.subject_id subjectId, chan.subject_name subjectName, chan.ccy ccy, chan.paid_fund paidFund, chan.undistribut_profits undistributProfits, chan.total_owner_equity totalOwnerEquity, chan.busi_date busiDate from prd_own_equity_chan chan
substring(chan.busi_date,1,7) = #{reportDate,jdbcType=VARCHAR}
AND chan.real_prd_id = #{prodId,jdbcType=VARCHAR}
ORDER BY chan.subject_id
